mapper.select:
/* selectGrCaseMtgList YOO.CHI.HOON */
WITH grCaseMtgList AS ( /* isry.itgcm.bizcmmns.cmmns.mapper.CaseMtgMapper.selectGrCaseMtgList(집단 사례회의목록) */ SELECT * FROM ( SELECT ROW_NUMBER() OVER(PARTITION BY T1.CASE_MTG_NO ORDER BY T1.CASE_MTG_NO) AS RNUM , T1.CASE_MTG_NO AS CASE_MTG_NO /* 사례회의번호(MT)*/ , T1.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호(CS)*/ , T1.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수*/ , T1.MTG_PRNMNT_YMD AS MTG_PRNMNT_YMD /* 회의예정일자*/ , T1.PRNMNT_BGNG_HR AS PRNMNT_BGNG_HR /* 예정시작시간*/ , T1.PRNMNT_END_HR AS PRNMNT_END_HR /* 예정종료시간*/ , T1.MTG_HDMT_YMD AS MTG_HDMT_YMD /* 회의개최일자*/ , T1.HDMT_BGNG_HR AS HDMT_BGNG_HR /* 개최시작시간*/ , T1.HDMT_END_HR AS HDMT_END_HR /* 개최종료시간*/ , T1.PLACE_NM AS PLACE_NM /* 장소명*/ , T1.ATDRN_NMST_CN AS ATDRN_NMST_CN /* 참석자명단내용*/ , T1.MTG_ITOAGD_CN AS MTG_ITOAGD_CN /* 회의안건내용*/ , T1.MTG_CN AS MTG_CN /* 회의내용*/ , T1.MTG_RESULT_CN AS MTG_RESULT_CN /* 회의결과내용*/ , T1.ATFINO AS ATFINO /* 첨부파일번호*/ , T1.DEL_YN AS DEL_YN /* 삭제여부*/ , T1.FRST_RGTR_ID AS FRST_RGTR_ID /* 최초등록자아이디*/ , T1.FRST_REG_DT AS FRST_REG_DT /* 최초등록일시*/ , T1.LAST_MDFR_ID AS LAST_MDFR_ID /* 최종수정자아이디*/ , T1.LAST_MDFCN_DT AS LAST_MDFCN_DT /* 최종수정일시*/ , T3.PIC_NO AS PIC_NO , (SELECT C##RG.DEC_B64(FLNM_ENCPT) FROM SCA100 WHERE ENFSN_NO = T3.PIC_NO ) AS PIC_NM , (SELECT INST_NM FROM SAA000 WHERE INST_NO = T3.PIC_INST_NO) AS INST_NM FROM SEB140 T1 /* 사례회의*/ , SEB100 T2 /* 사례기본*/ , SEB170 T3 /* 사례회의담당자*/ , SAA000 T4 /* 통합기관*/ WHERE 1 = 1 AND T1.CASE_MNG_NO = T2.CASE_MNG_NO AND T1.CASE_MTG_NO = T3.CASE_MTG_NO AND T4.INST_NO = T3.PIC_INST_NO AND T1.DEL_YN = 'N' /* 삭제여부*/
/* 권한추가*/
AND T1.MTG_HDMT_YMD BETWEEN TO_DATE(#{MTG_HDMT_BGNG_YMD} || '000000', 'YYYYMMDDHH24MISS') /* 회의개최일자*/ AND TO_DATE(#{MTG_HDMT_END_YMD} || '235959', 'YYYYMMDDHH24MISS') /* 회의개최일자*/
AND T1.MTG_ITOAGD_CN LIKE '%'|| #{MTG_ITOAGD_CN} || '%' /* 회의안건*/
AND T1.PLACE_NM LIKE '%'|| #{PLACE_NM} || '%' /* 회의장소*/
/* 집단사례회의상세 조회시 사용*/ AND T1.CASE_MTG_NO = #{CASE_MTG_NO} /* 사례회의 번호*/
) WHERE 1 = 1 AND RNUM = 1 )
CASE_MTG_NO /* 사례회의번호(MT)*/ , CASE_MNG_NO /* 사례관리번호(CS)*/ , CASE_MNG_ODRNO /* 사례관리차수*/ , MTG_PRNMNT_YMD /* 회의예정일자*/ , PRNMNT_BGNG_HR /* 예정시작시간*/ , PRNMNT_END_HR /* 예정종료시간*/ , MTG_HDMT_YMD /* 회의개최일자*/ , HDMT_BGNG_HR /* 개최시작시간*/ , HDMT_END_HR /* 개최종료시간*/ , PLACE_NM /* 장소명*/ , ATDRN_NMST_CN /* 참석자명단내용*/ , MTG_ITOAGD_CN /* 회의안건내용*/ , MTG_CN /* 회의내용*/ , MTG_RESULT_CN /* 회의결과내용*/ , ATFINO /* 첨부파일번호*/ , DEL_YN /* 삭제여부*/ , FRST_RGTR_ID /* 최초등록자아이디*/ , FRST_REG_DT /* 최초등록일시*/ , LAST_MDFR_ID /* 최종수정자아이디*/ , LAST_MDFCN_DT /* 최종수정일시*/ , PIC_NM /* 담당자명*/ , INST_NM /* 기관명 */ FROM grCaseMtgList ORDER BY CASE_MTG_NO DESC, MTG_HDMT_YMD DESC, FRST_REG_DT DESC

/* selectSEB160List YOO.CHI.HOON */ SELECT * FROM ( SELECT ROW_NUMBER() OVER(PARTITION BY ATDRN_NO ORDER BY ATDRN_NO) AS RNUM , CASE_MTG_NO , CASE_MNG_NO , CASE_MNG_ODRNO , ATDRN_NO , ATND_BGNG_HR , ATND_END_HR , RM_CN , DEL_YN , FRST_RGTR_ID , FRST_REG_DT , LAST_MDFR_ID , LAST_MDFCN_DT FROM SEB160 WHERE 1 = 1
AND ATDRN_NO = #{ATDRN_NO} /* 사례회의 참석자번호*/
AND CASE_MTG_NO = #{CASE_MTG_NO} /* 사례회의 번호*/
AND CASE_MNG_NO = #{CASE_MNG_NO} /* 사례관리 번호*/
AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO} /* 사례관리 차수번호*/
) WHERE RNUM = 1

/* selectSEB170List YOO.CHI.HOON */ SELECT * FROM ( SELECT ROW_NUMBER() OVER(PARTITION BY PIC_NO ORDER BY PIC_NO) AS RNUM , CASE_MTG_NO , CASE_MNG_NO , CASE_MNG_ODRNO , PIC_NO , PIC_INST_NO , PRCDNG_WRT_YN , RM_CN , DEL_YN , FRST_RGTR_ID , FRST_REG_DT , LAST_MDFR_ID , LAST_MDFCN_DT FROM SEB170 WHERE 1 = 1
AND PIC_NO = #{PIC_NO} /* 사례회의 담당자번호*/
AND CASE_MTG_NO = #{CASE_MTG_NO} /* 사례회의 번호*/
AND CASE_MNG_NO = #{CASE_MNG_NO} /* 사례관리 번호*/
AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO} /* 사례관리 차수번호*/
) WHERE RNUM = 1
